def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re
    import sys

    sys.setrecursionlimit(max(sys.getrecursionlimit(), 100000))

    token_pattern = re.compile(
        r"\s*(<=|>=|<>|[A-Z][1-9][0-9]?|SUM|MIN|MAX|IF|"
        r"[0-9]+|[+\-*/(),:=<>])"
    )

    def parse(content):
        tokens = token_pattern.findall(content[1:])
        pos = 0

        def expression():
            nonlocal pos
            node = term()
            while pos < len(tokens) and tokens[pos] in ("+", "-"):
                op = tokens[pos]
                pos += 1
                node = (op, node, term())
            return node

        def term():
            nonlocal pos
            node = unary()
            while pos < len(tokens) and tokens[pos] in ("*", "/"):
                op = tokens[pos]
                pos += 1
                node = (op, node, unary())
            return node

        def unary():
            nonlocal pos
            count = 0
            while tokens[pos] == "-":
                count += 1
                pos += 1
            node = atom()
            if count % 2:
                node = ("neg", node)
            return node

        def atom():
            nonlocal pos
            token = tokens[pos]
            pos += 1

            if token.isdigit():
                return ("number", int(token))

            if token == "(":
                node = expression()
                pos += 1  # )
                return node

            if token == "IF":
                pos += 1  # (
                left = expression()
                op = tokens[pos]
                pos += 1
                right = expression()
                pos += 1  # ,
                then = expression()
                pos += 1  # ,
                otherwise = expression()
                pos += 1  # )
                return ("if", op, left, right, then, otherwise)

            if token in ("SUM", "MIN", "MAX"):
                pos += 1  # (
                args = []
                while True:
                    if (
                        pos + 2 < len(tokens)
                        and tokens[pos][0].isalpha()
                        and tokens[pos] not in ("SUM", "MIN", "MAX", "IF")
                        and tokens[pos + 1] == ":"
                    ):
                        args.append(("range", tokens[pos], tokens[pos + 2]))
                        pos += 3
                    else:
                        args.append(expression())
                    if tokens[pos] == ")":
                        pos += 1
                        break
                    pos += 1  # ,
                return ("function", token, args)

            return ("cell", token)

        return expression()

    values = {}
    active = set()

    def evaluate_cell(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in active:
            return "#CYCLE!"

        active.add(name)
        content = cells[name]
        if content.startswith("="):
            value = evaluate(parse(content))
        else:
            value = int(content)
        active.remove(name)
        values[name] = value
        return value

    def evaluate(node):
        kind = node[0]

        if kind == "number":
            return node[1]

        if kind == "cell":
            return evaluate_cell(node[1])

        if kind == "neg":
            value = evaluate(node[1])
            return value if isinstance(value, str) else -value

        if kind in ("+", "-", "*", "/"):
            left = evaluate(node[1])
            if isinstance(left, str):
                return left
            right = evaluate(node[2])
            if isinstance(right, str):
                return right
            if kind == "+":
                return left + right
            if kind == "-":
                return left - right
            if kind == "*":
                return left * right
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient

        if kind == "if":
            op, left_node, right_node, then_node, else_node = node[1:]
            left = evaluate(left_node)
            if isinstance(left, str):
                return left
            right = evaluate(right_node)
            if isinstance(right, str):
                return right

            if op == "=":
                condition = left == right
            elif op == "<>":
                condition = left != right
            elif op == "<":
                condition = left < right
            elif op == "<=":
                condition = left <= right
            elif op == ">":
                condition = left > right
            else:
                condition = left >= right
            return evaluate(then_node if condition else else_node)

        function, args = node[1], node[2]
        result = None

        for arg in args:
            if arg[0] == "range":
                start, end = arg[1], arg[2]
                col1, col2 = sorted((ord(start[0]), ord(end[0])))
                row1, row2 = sorted((int(start[1:]), int(end[1:])))
                for row in range(row1, row2 + 1):
                    for col in range(col1, col2 + 1):
                        name = chr(col) + str(row)
                        if name not in cells:
                            continue
                        value = evaluate_cell(name)
                        if isinstance(value, str):
                            return value
                        if result is None:
                            result = value
                        elif function == "SUM":
                            result += value
                        elif function == "MIN":
                            result = min(result, value)
                        else:
                            result = max(result, value)
            else:
                value = evaluate(arg)
                if isinstance(value, str):
                    return value
                if result is None:
                    result = value
                elif function == "SUM":
                    result += value
                elif function == "MIN":
                    result = min(result, value)
                else:
                    result = max(result, value)

        return 0 if result is None else result

    for name in cells:
        evaluate_cell(name)

    return {name: values[name] for name in cells}
